/**
 * Newsletter template render — Handlebars wrapper.
 *
 * Used by the in-app preview endpoint and (T4 follow-up) by the n8n
 * send-time pipeline so a Workbench-style HTML email gets generated by
 * merging AI-assembled content into a stored Handlebars template.
 *
 * Compiles per-call. Sends are infrequent enough that the throughput
 * cost of recompiling vs caching by template id is irrelevant; the
 * upside is no stale-cache hazard when a user edits the template.
 *
 * Helpers registered:
 *   {{rank @index}}         pads (@index + 1) to two digits ("01", "07") so
 *                           the trending list matches the Course Worx sample
 *                           where each item is prefixed with "02", "04", etc.
 *   {{format_date d fmt}}   formats an ISO timestamp via a small
 *                           hand-rolled token map ("MMM D, YYYY", "ddd",
 *                           "h:mm a"). Avoids a dayjs/moment dependency.
 *
 * Triple-stash (`{{{x}}}`) is the caller's responsibility — fields named
 * `*_html` (intro_html, body_html, etc.) are intended to carry trusted
 * HTML produced by the AI pipeline. Two-stash escapes by default.
 */
import Handlebars from 'handlebars';

export interface RenderResult {
  html: string;
  warnings: string[];
}

let helpersRegistered = false;
function registerHelpers(): void {
  if (helpersRegistered) return;
  Handlebars.registerHelper('rank', (idx: unknown) => {
    const n = typeof idx === 'number' ? idx + 1 : Number(idx) + 1;
    if (!Number.isFinite(n)) return '';
    return String(n).padStart(2, '0');
  });
  Handlebars.registerHelper('format_date', (value: unknown, format: unknown) => {
    if (!value) return '';
    const d = new Date(String(value));
    if (Number.isNaN(d.getTime())) return String(value);
    const fmt = typeof format === 'string' ? format : 'MMM D, YYYY';
    return formatDateTokens(d, fmt);
  });
  helpersRegistered = true;
}

const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DAYS_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const DAYS_LONG = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

function formatDateTokens(d: Date, fmt: string): string {
  // Token order matters: longer tokens first so "MMMM" is not partly
  // consumed as "MMM"+"M".
  const replacements: Array<[string, string]> = [
    ['YYYY', String(d.getFullYear())],
    ['MMMM', MONTHS_SHORT[d.getMonth()]],          // we don't ship long month names yet
    ['MMM',  MONTHS_SHORT[d.getMonth()]],
    ['DDDD', DAYS_LONG[d.getDay()]],
    ['ddd',  DAYS_SHORT[d.getDay()]],
    ['DD',   String(d.getDate()).padStart(2, '0')],
    ['D',    String(d.getDate())],
    ['MM',   String(d.getMonth() + 1).padStart(2, '0')],
    ['mm',   String(d.getMinutes()).padStart(2, '0')],
    ['HH',   String(d.getHours()).padStart(2, '0')],
    ['h',    String(((d.getHours() + 11) % 12) + 1)],
    ['a',    d.getHours() < 12 ? 'am' : 'pm'],
  ];
  let out = fmt;
  for (const [tok, val] of replacements) out = out.split(tok).join(val);
  return out;
}

/**
 * Deep-merge `runtime` onto `fallback` so an AI payload that omits a
 * section (e.g. no `pull_quote`) falls back to the template's
 * sample_data — which is what makes the preview endpoint render even
 * with an empty body.
 *
 * - Plain objects merge recursively.
 * - Arrays are replaced wholesale (no element-wise merge — the trending
 *   list is array-of-records and an element-wise merge would produce
 *   nonsense if the AI returns a different number of items).
 * - Scalars / null are replaced if defined (undefined keeps fallback).
 */
function deepMerge(fallback: unknown, runtime: unknown): unknown {
  if (runtime === undefined) return fallback;
  if (runtime === null) return null;
  if (Array.isArray(runtime)) return runtime;
  if (typeof runtime !== 'object') return runtime;
  if (typeof fallback !== 'object' || fallback === null || Array.isArray(fallback)) {
    return runtime;
  }
  const out: Record<string, unknown> = { ...(fallback as Record<string, unknown>) };
  for (const k of Object.keys(runtime as Record<string, unknown>)) {
    out[k] = deepMerge(
      (fallback as Record<string, unknown>)[k],
      (runtime as Record<string, unknown>)[k],
    );
  }
  return out;
}

export interface RenderOptions {
  /** Optional design-time fallback merged under `data`. The DB column
   *  newsletter_templates_v2.sample_data feeds this at the route layer. */
  sampleData?: Record<string, unknown>;
}

export function renderTemplate(
  templateHtml: string,
  data: Record<string, unknown>,
  options: RenderOptions = {},
): RenderResult {
  registerHelpers();
  const warnings: string[] = [];
  const merged = options.sampleData
    ? (deepMerge(options.sampleData, data) as Record<string, unknown>)
    : data;

  // Handlebars.compile() is lazy — parse errors only surface when the
  // resulting template function is invoked. Calling Handlebars.parse()
  // eagerly forces the parse step so we can classify parse failures as
  // TemplateCompileError (4xx — caller error) and reserve TemplateRenderError
  // for runtime helper / data failures (5xx).
  try {
    Handlebars.parse(templateHtml);
  } catch (err) {
    throw new TemplateCompileError(
      `Template compile failed: ${(err as Error).message}`,
      err as Error,
    );
  }

  const compiled = Handlebars.compile(templateHtml, {
    noEscape: false,
    strict: false,
  });

  let html: string;
  try {
    html = compiled(merged);
  } catch (err) {
    throw new TemplateRenderError(
      `Template render failed: ${(err as Error).message}`,
      err as Error,
    );
  }

  // Light validation: a render that produces an empty body is almost always
  // a payload mismatch. Surface it as a warning rather than failing the
  // request — the preview endpoint should still return whatever rendered.
  if (html.trim().length === 0) {
    warnings.push('Rendered HTML is empty — template/data mismatch?');
  }

  return { html, warnings };
}

export class TemplateCompileError extends Error {
  constructor(message: string, public cause?: Error) {
    super(message);
    this.name = 'TemplateCompileError';
  }
}

export class TemplateRenderError extends Error {
  constructor(message: string, public cause?: Error) {
    super(message);
    this.name = 'TemplateRenderError';
  }
}

// Exported for tests so they can inspect the merge function in isolation
// without spinning up Handlebars.
export const _internal = { deepMerge, formatDateTokens };
